ALTER TABLE public.sap_produtos
  ADD COLUMN IF NOT EXISTS vendavel_sap boolean,
  ADD COLUMN IF NOT EXISTS listas_com_preco text,
  ADD COLUMN IF NOT EXISTS preco_vk12 numeric,
  ADD COLUMN IF NOT EXISTS preco_checado_em timestamptz,
  ADD COLUMN IF NOT EXISTS ativo_override boolean,
  ADD COLUMN IF NOT EXISTS ativo_override_por uuid,
  ADD COLUMN IF NOT EXISTS ativo_override_em timestamptz,
  ADD COLUMN IF NOT EXISTS ativo_override_motivo text;

COMMENT ON COLUMN public.sap_produtos.vendavel_sap IS 'Varredura de precos (VK12) no SAP: true = tem preco em alguma lista (vendavel).';
COMMENT ON COLUMN public.sap_produtos.ativo_override IS 'Override manual do flag ativo. NULL = segue a varredura automatica do SAP.';

