UPDATE public.sap_produtos p
SET vendavel_sap = false,
    listas_com_preco = NULL,
    preco_vk12 = NULL,
    preco_checado_em = now(),
    ativo = COALESCE(p.ativo_override, false)
WHERE p.origem = 'sap'
  AND NOT EXISTS (SELECT 1 FROM a WHERE a.codigo = p.codigo);

UPDATE public.produtos p
SET ativo = s.ativo
FROM public.sap_produtos s
WHERE s.codigo = p.codigo AND p.origem = 'sap';